from enum import Enum, IntEnum, Flag


class HttpStatus(IntEnum):
    OK = 200
    NOT_FOUND = 404
    ERROR = 500


class Color(Enum):
    RED = "red"
    GREEN = "green"
    BLUE = "blue"

    def is_primary(self):
        return self in (Color.RED, Color.BLUE)


class Permission(Flag):
    READ = 1
    WRITE = 2
    EXECUTE = 4
